262	func buildInCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
263		if len(call.Args) != 2 {
264			return nil, errors.New("in operator expects two arguments")
265		}
266	
267		// Handle identifier in list syntax.
268		if identName, err := getIdentName(call.Args[0]); err == nil {
269			if field, ok := pc.schema.Field(identName); ok && field.Kind == FieldKindVirtualAlias {
270				if _, aliasOk := pc.schema.ResolveAlias(identName); !aliasOk {
271					return nil, errors.Errorf("invalid alias %q", identName)
272				}
273			} else if !ok {
274				return nil, errors.Errorf("unknown identifier %q", identName)
275			}
276	
277			if listExpr := call.Args[1].GetListExpr(); listExpr != nil {
278				values := make([]ValueExpr, 0, len(listExpr.Elements))
279				for _, element := range listExpr.Elements {
280					value, err := buildValueExpr(element, pc)
281					if err != nil {
282						return nil, err
283					}
284					values = append(values, value)
285				}
286				return &InCondition{
287					Left:   &FieldRef{Name: identName},
288					Values: values,
289				}, nil
290			}
291		}
292	
293		// Handle "value in identifier" syntax.
294		if identName, err := getIdentName(call.Args[1]); err == nil {
295			if _, ok := pc.schema.Field(identName); !ok {
296				return nil, errors.Errorf("unknown identifier %q", identName)
297			}
298			element, err := buildValueExpr(call.Args[0], pc)
299			if err != nil {
300				return nil, err
301			}
302			return &ElementInCondition{
303				Element: element,
304				Field:   identName,
305			}, nil
306		}
307	
308		return nil, errors.New("invalid use of in operator")
309	}
