650	// buildTimestampAccessor converts created_ts.getMonth() into a FieldAccessorValue.
651	// A `now` target folds to a literal date part of the frozen evaluation time, so
652	// expressions like created_ts.getMonth() == now.getMonth() stay dynamic per compile.
653	// Timezone arguments are rejected; extraction is UTC (see renderer).
654	func buildTimestampAccessor(call *exprv1.Expr_Call, pc parseContext) (ValueExpr, error) {
655		targetName, err := getIdentName(call.Target)
656		if err != nil {
657			return nil, errors.Wrap(err, "timestamp accessor requires a field target")
658		}
659		if len(call.Args) != 0 {
660			return nil, errors.Errorf("%s() with a timezone argument is not supported", call.Function)
661		}
662		if targetName == "now" {
663			return &LiteralValue{Value: foldNowAccessor(call.Function, pc.now)}, nil
664		}
665		field, ok := pc.schema.Field(targetName)
666		if !ok {
667			return nil, errors.Errorf("unknown identifier %q", targetName)
668		}
669		if field.Type != FieldTypeTimestamp {
670			return nil, errors.Errorf("%s() is only valid on timestamp fields, got %q", call.Function, targetName)
671		}
672		return &FieldAccessorValue{Field: targetName, Accessor: call.Function}, nil
673	}
674	
675	// foldNowAccessor evaluates a timestamp accessor against the frozen evaluation
676	// time in UTC, matching CEL result bases (0-based month, day-of-month, day-of-week
677	// with 0 = Sunday, and day-of-year; 1-based getDate).
678	func foldNowAccessor(accessor string, now time.Time) int64 {
679		t := now.UTC()
680		switch accessor {
681		case "getFullYear":
682			return int64(t.Year())
683		case "getMonth":
684			return int64(t.Month()) - 1
685		case "getDate":
686			return int64(t.Day())
687		case "getDayOfMonth":
688			return int64(t.Day()) - 1
689		case "getDayOfWeek":
690			return int64(t.Weekday())
691		case "getDayOfYear":
692			return int64(t.YearDay()) - 1
693		case "getHours":
694			return int64(t.Hour())
695		case "getMinutes":
696			return int64(t.Minute())
697		case "getSeconds":
698			return int64(t.Second())
699		}
700		return 0
701	}
