803	// buildComprehensionCondition handles CEL comprehension expressions (exists, all, etc.).
804	func buildComprehensionCondition(comp *exprv1.Expr_Comprehension, schema Schema) (Condition, error) {
805		// Determine the comprehension kind by examining the loop initialization and step
806		kind, err := detectComprehensionKind(comp)
807		if err != nil {
808			return nil, err
809		}
810	
811		// Get the field being iterated over
812		iterRangeIdent := comp.IterRange.GetIdentExpr()
813		if iterRangeIdent == nil {
814			return nil, errors.New("comprehension range must be a field identifier")
815		}
816		fieldName := iterRangeIdent.GetName()
817	
818		// Validate the field
819		field, ok := schema.Field(fieldName)
820		if !ok {
821			return nil, errors.Errorf("unknown field %q in comprehension", fieldName)
822		}
823		if field.Kind != FieldKindJSONList {
824			return nil, errors.Errorf("field %q does not support comprehension (must be a list)", fieldName)
825		}
826	
827		// Extract the predicate from the loop step
828		predicate, err := extractPredicate(comp, schema)
829		if err != nil {
830			return nil, err
831		}
832	
833		return &ListComprehensionCondition{
834			Kind:      kind,
835			Field:     fieldName,
836			IterVar:   comp.IterVar,
837			Predicate: predicate,
838		}, nil
839	}
840	
841	// detectComprehensionKind determines if this is an exists() macro.
842	// Only exists() is currently supported.
843	func detectComprehensionKind(comp *exprv1.Expr_Comprehension) (ComprehensionKind, error) {
844		// Check the accumulator initialization
845		accuInit := comp.AccuInit.GetConstExpr()
846		if accuInit == nil {
847			return "", errors.New("comprehension accumulator must be initialized with a constant")
848		}
849	
850		// exists() starts with false and uses OR (||) in loop step
851		if !accuInit.GetBoolValue() {
852			if step := comp.LoopStep.GetCallExpr(); step != nil && step.Function == "_||_" {
853				return ComprehensionExists, nil
854			}
855		}
856	
857		// all() starts with true and uses AND (&&) in the loop step.
858		if accuInit.GetBoolValue() {
859			if step := comp.LoopStep.GetCallExpr(); step != nil && step.Function == "_&&_" {
860				return ComprehensionAll, nil
861			}
862		}
863	
864		// exists_one() starts at int(0) and increments via a conditional (predicate ?
865		// accu + 1 : accu) in the loop step.
866		if _, isInt := accuInit.GetConstantKind().(*exprv1.Constant_Int64Value); isInt {
867			if step := comp.LoopStep.GetCallExpr(); step != nil && step.Function == "_?_:_" {
868				return ComprehensionExistsOne, nil
869			}
870		}
871	
872		return "", errors.New("unsupported comprehension type (supported: exists, all, exists_one)")
873	}
874	
875	// extractPredicate extracts the predicate expression from the comprehension loop step.
876	func extractPredicate(comp *exprv1.Expr_Comprehension, _ Schema) (PredicateExpr, error) {
877		// The loop step is: @result || predicate(t) for exists
878		//                or: @result && predicate(t) for all
879		step := comp.LoopStep.GetCallExpr()
880		if step == nil {
881			return nil, errors.New("comprehension loop step must be a call expression")
882		}
883	
884		// exists/all: accu || predicate  /  accu && predicate  -> predicate is arg[1].
885		// exists_one: predicate ? accu + 1 : accu               -> predicate is arg[0].
886		var predicateExpr *exprv1.Expr
887		if step.Function == "_?_:_" {
888			if len(step.Args) != 3 {
889				return nil, errors.New("exists_one loop step must have three arguments")
890			}
891			predicateExpr = step.Args[0]
892		} else {
893			if len(step.Args) != 2 {
894				return nil, errors.New("comprehension loop step must have two arguments")
895			}
896			predicateExpr = step.Args[1]
897		}
898		predicateCall := predicateExpr.GetCallExpr()
899		if predicateCall == nil {
900			return nil, errors.New("comprehension predicate must be a function call")
901		}
902	
903		// Handle different predicate functions
904		switch predicateCall.Function {
905		case "_==_":
906			return buildEqualsPredicate(predicateCall, comp.IterVar)
907		case "startsWith":
908			return buildStartsWithPredicate(predicateCall, comp.IterVar)
909		case "endsWith":
910			return buildEndsWithPredicate(predicateCall, comp.IterVar)
911		case "contains":
912			return buildContainsPredicate(predicateCall, comp.IterVar)
913		default:
914			return nil, errors.Errorf(`unsupported predicate function %q in comprehension (supported: ==, startsWith, endsWith, contains)`, predicateCall.Function)
915		}
916	}
917	
918	// buildEqualsPredicate extracts the value from t == "value".
919	func buildEqualsPredicate(call *exprv1.Expr_Call, iterVar string) (PredicateExpr, error) {
920		if len(call.Args) != 2 {
921			return nil, errors.New("equality predicate expects exactly two arguments")
922		}
923	
924		var constExpr *exprv1.Expr
925		switch {
926		case isIterVarExpr(call.Args[0], iterVar):
927			constExpr = call.Args[1]
928		case isIterVarExpr(call.Args[1], iterVar):
929			constExpr = call.Args[0]
930		default:
931			return nil, errors.Errorf("equality predicate must compare against the iteration variable %q", iterVar)
932		}
933	
934		value, err := getConstValue(constExpr)
935		if err != nil {
936			return nil, errors.Wrap(err, "equality argument must be a constant string")
937		}
938	
939		valueStr, ok := value.(string)
940		if !ok {
941			return nil, errors.New("equality argument must be a string")
942		}
943	
944		return &EqualsPredicate{Value: valueStr}, nil
945	}
